   314	function isConnectionUnverified(policy: OnyxEntry<Policy>, connectionName: PolicyConnectionName): boolean {
   315	    // A verified connection is one that has been successfully synced at least once
   316	    // We'll always err on the side of considering a connection as verified connected even if we can't find a lastSync property saying as such
   317	    // i.e. this is a property that is explicitly set to false, not just missing
   318	    if (connectionName === CONST.POLICY.CONNECTIONS.NAME.NETSUITE) {
   319	        return !(policy?.connections?.[CONST.POLICY.CONNECTIONS.NAME.NETSUITE]?.verified ?? true);
   320	    }
   321	
   322	    // If the connection has no lastSync property, we'll consider it unverified
   323	    if (isEmptyObject(policy?.connections?.[connectionName]?.lastSync)) {
   324	        return true;
   325	    }
   326	
   327	    return !(policy?.connections?.[connectionName]?.lastSync?.isConnected ?? true);
   328	}
