   365	function isConnectionInProgress(connectionSyncProgress: OnyxEntry<PolicyConnectionSyncProgress>, policy?: OnyxEntry<Policy>): boolean {
   366	    if (!policy || !connectionSyncProgress) {
   367	        return false;
   368	    }
   369	
   370	    const qboConnection = policy?.connections?.quickbooksOnline;
   371	
   372	    const lastSyncProgressDate = parseISO(connectionSyncProgress?.timestamp ?? '');
   373	    return (
   374	        (!!connectionSyncProgress?.stageInProgress &&
   375	            (connectionSyncProgress.stageInProgress !== CONST.POLICY.CONNECTIONS.SYNC_STAGE_NAME.JOB_DONE || !policy?.connections?.[connectionSyncProgress.connectionName]) &&
   376	            isValid(lastSyncProgressDate) &&
   377	            differenceInMinutes(new Date(), lastSyncProgressDate) < CONST.POLICY.CONNECTIONS.SYNC_STAGE_TIMEOUT_MINUTES) ||
   378	        (!!qboConnection && !qboConnection?.data && !!qboConnection?.config?.credentials)
   379	    );
   380	}
